import re,json,sqlite3,collections
B12={'UN','ISO','INT','CA','US','UK','DE','NO','SE','JP','AU','EU','SG','NZ','IE','FR','ES','PT','FI','NL','KR'}
t=open('references/standards-registry.md',encoding='utf-8').read()
ents=[]
for b in re.findall(r"\`\`\`yaml\n(.*?)\`\`\`",t,re.S):
    d={}
    for l in b.splitlines():
        m=re.match(r'(\w+):\s*"?(.*?)"?\s*$',l)
        if m: d[m.group(1)]=m.group(2)
    if d.get('jurisdiction') in B12 and d.get('standard_cited'): ents.append(d)
c=sqlite3.connect('file:data/guidebook.db?mode=ro',uri=True)
leads=c.execute("select jurisdiction,standard_name,coalesce(clause,''),status from research_code_leads order by jurisdiction,lead_id").fetchall()
co1=json.load(open('references/co1-verified-sources.json')); co2=json.load(open('references/co2-verified-sources.json'))
out=["# Major-sources worklist, bucket 1-2 jurisdictions (derived $(date -u +%F); a LEAD LIST, not evidence)\n",
"Built from references/standards-registry.md (as of its own dates), research_code_leads, references/co1-verified-sources.json, references/co2-verified-sources.json. Every item still has to be re-retrieved and admitted on its own evidence (DR-2026-08-06 section 4.1).\n",
"## Code bodies and standards (standards-registry, bucket 1-2 + INT)\n","| Jur | Standard cited | Current version per registry | Status | Source URL |","|---|---|---|---|---|"]
for e in sorted(ents,key=lambda e:(e['jurisdiction'],e['standard_cited'])):
    out.append(f"| {e['jurisdiction']} | {e['standard_cited'][:90]} | {e.get('current_version','')[:90]} | {e.get('status','')} | {e.get('source_url','')[:110]} |")
out+=["\n## Code leads already in the database (research_code_leads)\n","| Jur | Standard | Clause | Status |","|---|---|---|---|"]
for j,s,cl,st in leads: out.append(f"| {j} | {s[:100]} | {cl[:40]} | {st} |")
out+=["\n## Advocacy and lived-experience bodies (co1-verified-sources.json)\n"]
for x in co1: out.append(f"- {x.get('authors','')[:70]} ({x.get('year','')}) {x.get('title','')[:80]} {x.get('url','') or ''}")
out+=["\n## Occupational-therapy professional bodies (co2-verified-sources.json)\n"]
for x in co2: out.append(f"- {x.get('authors','')[:70]} ({x.get('year','')}) {x.get('title','')[:80]}")
p='scratchpad/$STEM/major-sources-worklist.md'
open(p,'w',encoding='utf-8').write('\n'.join(out)+'\n')
print(p, len(ents),'registry entries in scope;',len(leads),'code leads;',len(co1),'Co-1;',len(co2),'Co-2')
print(collections.Counter(e['jurisdiction'] for e in ents))
