            kind = rnd.choice(["utf8", "utf8", "html", "latin1", "utf16", "binary", "cjk"])
            text = ". ".join(sentence() for _ in range(rnd.randint(3, 8)))
            ref = rnd.choice([None, "REF-00001", "REF-00002", "REF-00003", "REF-00004"])
            name = f"{sess[-1]}{i}.{ 'html' if kind=='html' else 'txt'}"
            ctype = None
            if kind == "utf8": raw = text.encode("utf-8")
            elif kind == "html": raw = f"<p>{text.replace('. ', '</p><p>')}</p>".encode(); ctype = "text/html; charset=utf-8"
            elif kind == "latin1": text += " café naïve"; raw = text.encode("latin-1"); ctype = "text/plain; charset=iso-8859-1"
            elif kind == "utf16": raw = b"\xff\xfe" + text.encode("utf-16-le")
            elif kind == "cjk": text = "勾配は、十二分の一 " + text; raw = text.encode("utf-8")
            else: raw = bytes(rnd.randrange(256) for _ in range(200)) + b"\xff\xfe\xfa"; text = None
            open(os.path.join(d, name), "wb").write(raw)
            rec = {"artefact": name, "sha256": "x", "url": f"http://example/{sess}/{i}"}
            if ref: rec["ref_id"] = ref
            if ctype: rec["content_type"] = ctype
            recs.append(rec); bodies.append((sess, name, ref, text))
        if sess == "session_C":
            recs.append({"artefact": "ghost.txt", "ref_id": "REF-00001"})       # manifest line, no file
            if with_dir:
                os.makedirs(os.path.join(d, "dirartefact.txt")); recs.append({"artefact": "dirartefact.txt", "ref_id": "REF-00001"})
        if sess == "session_B" and bodies:
            recs.append(dict(recs[0]))                                            # duplicate manifest line
        open(os.path.join(d, "manifest.jsonl"), "w").write("\n".join(json.dumps(r) for r in recs) + "\n")
    return bodies

def mutate(q):
    k = rnd.randrange(6)
    if k == 0: return q.upper()
    if k == 1: return "  ".join(q.split())
    if k == 2: return q.replace(" ", ", ")
    if k == 3: return q[: max(3, len(q) // 2)]
    if k == 4: return q + " zzqx unlikely tail"
    return q

def queries(bodies):
    qs = []
    texts = [b for b in bodies if b[3]]
    for _ in range(300):
        s, n, ref, t = rnd.choice(texts)
        sents = [x for x in t.split(". ") if len(x) > 8]
        q = mutate(rnd.choice(sents)) if sents else t
        for r in (ref, "REF-00001", "REF-00002", "REF-99999", None):
            for sess in (None, None, None, s, s + ".md", "session_nonexistent"):
                qs.append({"quote": q, "ref": r, "session": sess})
