        a, b = run(OLD, root, qf), run(NEW, root, qf)
        d = [(q, x, y) for q, x, y in zip(qs, a, b) if x != y]
        tot += len(qs); diff += len(d)
        kinds = {}
        for x in b: kinds[x[0]] = kinds.get(x[0], 0) + 1
