con = sqlite3.connect(f"file:{repo}/data/guidebook.db?mode=ro", uri=True)
files = [repo / "scripts/db.py", repo / "scripts/assess/assess_cell.py", repo / "scripts/dbcore.py"] + sorted((repo / "scripts/research").glob("*.py")) + [repo / "scripts/emit_data_migration.py", repo / "scripts/resolve_dois.py", repo / "scripts/verify_urls.py"]
funcs = []   # (file, name, [strings])
for f in files:
    if not f.exists(): continue
    tree = ast.parse(f.read_text(encoding="utf-8"))
    for fn in ast.walk(tree):
        if isinstance(fn, (ast.FunctionDef, ast.AsyncFunctionDef)):
            ss = []
            for n in ast.walk(fn):
                if isinstance(n, ast.Constant) and isinstance(n.value, str): ss.append(n.value)
                elif isinstance(n, ast.JoinedStr): ss.append("".join(v.value if isinstance(v, ast.Constant) else " " for v in n.values))
            funcs.append((f.name, fn.name, ss))
tables = [r[0] for r in con.execute("select name from sqlite_master where type='table' and name not like 'sqlite_%'")]
vocab = {}
for t in tables:
    ddl = con.execute("select sql from sqlite_master where name=?", (t,)).fetchone()[0] or ""
    cs = {c[1] for c in con.execute(f'pragma table_info("{t}")')}
    for m in re.finditer(r"(\w+)\s+IN\s*\(\s*((?:'[^']*'\s*,?\s*)+)\)", ddl, re.I):
        col = m.group(1)
        if col in cs:
            vals = re.findall(r"'([^']*)'", m.group(2))
            if 2 <= len(vals) <= 14: vocab.setdefault(t, {})[col] = vals
res = {}
for t, cols in vocab.items():
    for c, vals in cols.items():
        for v in vals:
            prod = []
            for fl, fname, ss in funcs:
