                if re.search(rf"['\"]{re.escape(v)}['\"]", joined) and (re.search(rf"\b{t}\b", joined) or re.search(rf"\b{c}\b", joined)):
                    prod.append(f"{fl}:{fname}")
            res[f"{t}.{c}={v}"] = sorted(set(prod))[:6]
json.dump(res, open(sys.argv[2], "w"), indent=1)
zero = [k for k, v in res.items() if not v]
print("vocabulary values:", len(res), "| with no heuristic producer:", len(zero))
